import{_ as o,r as s,o as l,c as p,e as a,a as c,s as i}from"./chunks/framework.CXcwiNg-.js";const b=JSON.parse('{"title":"Models - October CMS - 4.x","titleTemplate":false,"description":"The available models provided by Tailor.","frontmatter":{"subtitle":"The available models provided by Tailor."},"headers":[{"level":2,"title":"Model Classes","slug":"model-classes","link":"#model-classes","children":[]},{"level":2,"title":"Entry Records","slug":"entry-records","link":"#entry-records","children":[{"level":3,"title":"Structure Entry","slug":"structure-entry","link":"#structure-entry","children":[]},{"level":3,"title":"Stream Entry","slug":"stream-entry","link":"#stream-entry","children":[]},{"level":3,"title":"Retrieving Multiple Entries","slug":"retrieving-multiple-entries","link":"#retrieving-multiple-entries","children":[]},{"level":3,"title":"Retrieving a Single Entry","slug":"retrieving-a-single-entry","link":"#retrieving-a-single-entry","children":[]},{"level":3,"title":"Inserting & Updating Entries","slug":"inserting-updating-entries","link":"#inserting-updating-entries","children":[]}]},{"level":2,"title":"Global Record","slug":"global-record","link":"#global-record","children":[{"level":3,"title":"Available Attributes","slug":"available-attributes","link":"#available-attributes","children":[]},{"level":3,"title":"Retrieving a Global Record","slug":"retrieving-a-global-record","link":"#retrieving-a-global-record","children":[]}]},{"level":2,"title":"Working With Related Fields","slug":"working-with-related-fields","link":"#working-with-related-fields","children":[{"level":3,"title":"Eager Loading Relations","slug":"eager-loading-relations","link":"#eager-loading-relations","children":[]},{"level":3,"title":"Creating Related Fields","slug":"creating-related-fields","link":"#creating-related-fields","children":[]}]},{"level":2,"title":"Extending Model Constructors","slug":"extending-model-constructors","link":"#extending-model-constructors","children":[]},{"level":2,"title":"Extending Tailor Models","slug":"extending-tailor-models","link":"#extending-tailor-models","children":[{"level":3,"title":"Replacing the Entire Model","slug":"replacing-the-entire-model","link":"#replacing-the-entire-model","children":[]},{"level":3,"title":"Associating Tailor to Regular Models","slug":"associating-tailor-to-regular-models","link":"#associating-tailor-to-regular-models","children":[]},{"level":3,"title":"Associating Regular Models to Tailor","slug":"associating-regular-models-to-tailor","link":"#associating-regular-models-to-tailor","children":[]},{"level":3,"title":"Building a Custom Content Field","slug":"building-a-custom-content-field","link":"#building-a-custom-content-field","children":[{"level":4,"title":"See Also","slug":"see-also","link":"#see-also","children":[]}]}]}],"relativePath":"4.x/cms/tailor/models.md","filePath":"4.x/cms/tailor/models.md"}'),r={name:"4.x/cms/tailor/models.md"};function d(u,n,g,k,h,m){const e=s("pre-heading"),t=s("post-heading");return l(),p("div",null,[a(e),n[0]||(n[0]=c("h1",null,"Models",-1)),a(t),n[1]||(n[1]=i(`<p>This article describes how to interact with Tailor using PHP and the available models.</p><h2 id="model-classes"><a href="#model-classes" class="header-anchor">#</a> Model Classes</h2><p>The following model classes can be observed to their associated blueprint types.</p><div class="table"><table tabindex="0"><thead><tr><th>Model Class</th><th>Blueprint Type</th></tr></thead><tbody><tr><td><code>Tailor\\Models\\EntryRecord</code></td><td>entry</td></tr><tr><td><code>Tailor\\Models\\StructureRecord</code></td><td>structure</td></tr><tr><td><code>Tailor\\Models\\StreamRecord</code></td><td>stream</td></tr><tr><td><code>Tailor\\Models\\SingleRecord</code></td><td>single</td></tr><tr><td><code>Tailor\\Models\\GlobalRecord</code></td><td>global</td></tr></tbody></table></div><h2 id="entry-records"><a href="#entry-records" class="header-anchor">#</a> Entry Records</h2><p>The <code>EntryRecord</code> model is base model used to store content for an entry. In addition to your defined form fields, the following attributes can be found on the retrieved model.</p><div class="table"><table tabindex="0"><thead><tr><th>Attribute</th><th>Description</th></tr></thead><tbody><tr><td><strong>id</strong></td><td>The Primary Key found in the database.</td></tr><tr><td><strong>blueprint_uuid</strong></td><td>The UUID of the associated blueprint.</td></tr><tr><td><strong>content_group</strong></td><td>The content group name, if used.</td></tr><tr><td><strong>title</strong></td><td>A title descriptor for the entry, for example, <strong>My Blog Post</strong>.</td></tr><tr><td><strong>slug</strong></td><td>A slug identifier for the entry, for example, <code>my-blog-post</code>.</td></tr><tr><td><strong>is_enabled</strong></td><td>Determines if the entry is currently visible.</td></tr><tr><td><strong>created_at</strong></td><td>The creation date for the entry.</td></tr><tr><td><strong>updated_at</strong></td><td>The last updated date for the entry.</td></tr><tr><td><strong>expired_at</strong></td><td>The expiry date for the entry.</td></tr><tr><td><strong>published_at</strong></td><td>The published date for the entry.</td></tr><tr><td><strong>published_at_date</strong></td><td>The published date, or if none is specified, the creation date.</td></tr></tbody></table></div><h3 id="structure-entry"><a href="#structure-entry" class="header-anchor">#</a> Structure Entry</h3><p>The <code>StructureRecord</code> model extends the <code>EntryRecord</code> and is used to store content for an structured entries. If an entry type is a <code>structure</code>, it will resolve to this model and have some extra attributes.</p><div class="table"><table tabindex="0"><thead><tr><th>Attribute</th><th>Description</th></tr></thead><tbody><tr><td><strong>fullslug</strong></td><td>A slug identifier that includes parent slugs, for example, <code>parent-slug/child-slug</code>.</td></tr><tr><td><strong>parent</strong></td><td>The parent record for this entry, if available.</td></tr><tr><td><strong>children</strong></td><td>The child records for this entry, if available.</td></tr></tbody></table></div><h3 id="stream-entry"><a href="#stream-entry" class="header-anchor">#</a> Stream Entry</h3><p>The <code>StreamRecord</code> model extends the <code>EntryRecord</code> model is used to store content for streamed entries. If an entry type is a <code>stream</code>, it will have some extra attributes.</p><div class="table"><table tabindex="0"><thead><tr><th>Attribute</th><th>Description</th></tr></thead><tbody><tr><td><strong>published_at_day</strong></td><td>The numerical day the entry was published.</td></tr><tr><td><strong>published_at_month</strong></td><td>The numerical month the entry was published.</td></tr><tr><td><strong>published_at_year</strong></td><td>The numerical year the entry was published.</td></tr></tbody></table></div><h3 id="retrieving-multiple-entries"><a href="#retrieving-multiple-entries" class="header-anchor">#</a> Retrieving Multiple Entries</h3><p>To work with an entry using PHP, you may use the model class (e.g. <code>EntryRecord</code>) and call the <code>inSection</code> static method, passing the handle to return a prepared <a href="./../../extend/database/query.html">database model query</a>. Alternatively, you can look it up using the UUID and the <code>inSectionUuid</code> method.</p><p>The following <code>get</code> method query returns <a href="./../../extend/services/collection.html">a collection of records</a>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$records</span> <span class="token operator">=</span> <span class="token class-name static-context">EntryRecord</span><span class="token operator">::</span><span class="token function">inSection</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Blog\\Post&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token variable">$records</span> <span class="token operator">=</span> <span class="token class-name static-context">EntryRecord</span><span class="token operator">::</span><span class="token function">inSectionUuid</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;a63fabaf-7c0b-4c74-b36f-7abf1a3ad1c1&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="retrieving-a-single-entry"><a href="#retrieving-a-single-entry" class="header-anchor">#</a> Retrieving a Single Entry</h3><p>Combined with the <code>where</code> constraint, you may find a single record with the <code>first</code> method. The following will find an entry where the slug is equal to <strong>first-post</strong>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$record</span> <span class="token operator">=</span> <span class="token class-name static-context">EntryRecord</span><span class="token operator">::</span><span class="token function">inSection</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Blog\\Post&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">where</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;slug&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;first-post&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">first</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>If an <a href="./../tailor/blueprints.html">entry type</a> is set to <code>single</code>, you can use the <code>findSingleForSection</code> method to look up the entry. Likewise, the <code>findSingleForSectionUuid</code> can be used for looking up by the UUID. These methods will ensure a record exists during lookup.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$record</span> <span class="token operator">=</span> <span class="token class-name static-context">SingleRecord</span><span class="token operator">::</span><span class="token function">findSingleForSection</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Homepage&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token variable">$record</span> <span class="token operator">=</span> <span class="token class-name static-context">SingleRecord</span><span class="token operator">::</span><span class="token function">findSingleForSectionUuid</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;3328c303-7989-462e-b866-27e7037ba275&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="inserting-updating-entries"><a href="#inserting-updating-entries" class="header-anchor">#</a> Inserting &amp; Updating Entries</h3><p>The <code>inSection</code> method can be used to create records dynamically. The following will create a new blog post entry. The same code can be used to update an existing record after retrieving it first.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$post</span> <span class="token operator">=</span> <span class="token class-name static-context">EntryRecord</span><span class="token operator">::</span><span class="token function">inSection</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Blog\\Post&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token variable">$post</span><span class="token operator">-&gt;</span><span class="token property">title</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;Imported Post&#39;</span><span class="token punctuation">;</span>
<span class="token variable">$post</span><span class="token operator">-&gt;</span><span class="token function">save</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="global-record"><a href="#global-record" class="header-anchor">#</a> Global Record</h2><p>The <code>GlobalRecord</code> model is used to store content for a global.</p><h3 id="available-attributes"><a href="#available-attributes" class="header-anchor">#</a> Available Attributes</h3><p>In addition to the defined form fields, the following attributes can be found on the retrieved model.</p><div class="table"><table tabindex="0"><thead><tr><th>Attribute</th><th>Description</th></tr></thead><tbody><tr><td><strong>id</strong></td><td>The Primary Key found in the database.</td></tr><tr><td><strong>blueprint_uuid</strong></td><td>The UUID of the associated blueprint.</td></tr></tbody></table></div><h3 id="retrieving-a-global-record"><a href="#retrieving-a-global-record" class="header-anchor">#</a> Retrieving a Global Record</h3><p>To look up a global using PHP, you may use the <code>Tailor\\Models\\GlobalRecord</code> model and call the <code>findForGlobal</code> static method, passing the handle. Alternatively, you can look it up using the UUID and the <code>findForGlobalUuid</code> method.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">GlobalRecord</span><span class="token operator">::</span><span class="token function">findForGlobal</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Blog\\Config&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token class-name static-context">GlobalRecord</span><span class="token operator">::</span><span class="token function">findForGlobalUuid</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;7b193500-ac0b-481f-a79c-2a362646364d&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="working-with-related-fields"><a href="#working-with-related-fields" class="header-anchor">#</a> Working With Related Fields</h2><p>Related fields can include <a href="./../../element/form/widget-repeater.html">repeater fields</a> and <a href="./../../element/content/field-entries.html">entries fields</a>, and there are some extra steps needed to read and write to these fields.</p><h3 id="eager-loading-relations"><a href="#eager-loading-relations" class="header-anchor">#</a> Eager Loading Relations</h3><p>When reading related fields, you can eager load them on the collection using the <code>load</code> method. This method makes the related content available as a single query and is best for performance.</p><p>The following eager loads the <strong>categories</strong> field and adds it to the result, along with an example of passing multiple related fields.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$records</span><span class="token operator">-&gt;</span><span class="token function">load</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;categories&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token variable">$records</span><span class="token operator">-&gt;</span><span class="token function">load</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;categories&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;author&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="creating-related-fields"><a href="#creating-related-fields" class="header-anchor">#</a> Creating Related Fields</h3><p>When writing related fields, you can call the relation name as a method to return the relationship definition, then a subsequent <code>create()</code> method can be called, which returns the newly created relation.</p><p>The following locates the first blog post in the <strong>Blog\\Post</strong> section and then creates an associated category.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$post</span> <span class="token operator">=</span> <span class="token class-name static-context">EntryRecord</span><span class="token operator">::</span><span class="token function">inSection</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Blog\\Post&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">first</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token variable">$post</span><span class="token operator">-&gt;</span><span class="token function">categories</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">create</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;title&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Test&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;price&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;100&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Use the <code>make()</code> method to create a new empty model instance.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$category</span> <span class="token operator">=</span> <span class="token variable">$post</span><span class="token operator">-&gt;</span><span class="token function">categories</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">make</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>If the category already exists, use the <code>add()</code> method instead. The following adds the first blog category to the first blog post.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$post</span> <span class="token operator">=</span> <span class="token class-name static-context">EntryRecord</span><span class="token operator">::</span><span class="token function">inSection</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Blog\\Post&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">first</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token variable">$category</span> <span class="token operator">=</span> <span class="token class-name static-context">EntryRecord</span><span class="token operator">::</span><span class="token function">inSection</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Blog\\Category&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">first</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token variable">$post</span><span class="token operator">-&gt;</span><span class="token function">categories</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">add</span><span class="token punctuation">(</span><span class="token variable">$category</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><div class="custom-block tip"><p>View the <a href="./../../extend/database/relations.html">relations article</a> to learn more about model relationships.</p></div><h2 id="extending-model-constructors"><a href="#extending-model-constructors" class="header-anchor">#</a> Extending Model Constructors</h2><p>Similar to <a href="./../../extend/extending.html">extending regular models</a>, you may extend the <code>EntryRecord</code> model constructor using the <code>extendInSection</code> method to target a specific blueprint. The <code>extendInSectionUuid</code> method can also be used for more precise targeting.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">EntryRecord</span><span class="token operator">::</span><span class="token function">extendInSection</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Blog\\Post&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$model</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token function">bindEvent</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;model.afterDelete&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token keyword">use</span> <span class="token punctuation">(</span><span class="token variable">$model</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token comment">// Model has been deleted!</span>
    <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>The <code>GlobalRecord</code> model constructor also supports extension using the <code>extendInGlobal</code> and <code>extendInGlobalUuid</code> methods to target a specific blueprint.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">GlobalRecord</span><span class="token operator">::</span><span class="token function">extendInGlobal</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Blog\\Config&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$model</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token function">bindEvent</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;model.beforeSave&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token keyword">use</span> <span class="token punctuation">(</span><span class="token variable">$model</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token comment">// Model has been saved!</span>
    <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><div class="custom-block tip"><p>The <code>extendInSectionUuid</code> and <code>extendInGlobalUuid</code> methods will not throw an exception if the blueprint is not found.</p></div><h2 id="extending-tailor-models"><a href="#extending-tailor-models" class="header-anchor">#</a> Extending Tailor Models</h2><p>In some cases you may want to combine tailor models with <a href="./../../extend/system/models.html">regular database models</a>.</p><h3 id="replacing-the-entire-model"><a href="#replacing-the-entire-model" class="header-anchor">#</a> Replacing the Entire Model</h3><p>Use the <code>modelClass</code> blueprint property when you need Tailor blueprints to include more complex functionality. This will resolve the blueprint to a custom model instance.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">handle</span><span class="token punctuation">:</span> Blog\\Post
<span class="token key atrule">type</span><span class="token punctuation">:</span> stream
<span class="token key atrule">name</span><span class="token punctuation">:</span> Blog Post
<span class="token key atrule">modelClass</span><span class="token punctuation">:</span> App\\Models\\TailorBlogPost
<span class="token comment"># ...</span>
</code></pre></div><p>It is important that the model defined extends the exact model class used by the blueprint type. In the above example, we must extend the <code>StreamRecord</code> class since it uses the <code>stream</code> type.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">namespace</span> <span class="token package">App<span class="token punctuation">\\</span>Models</span><span class="token punctuation">;</span>

<span class="token keyword">use</span> <span class="token package">Tailor<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>StreamRecord</span><span class="token punctuation">;</span>

<span class="token keyword">class</span> <span class="token class-name-definition class-name">TailorBlogPost</span> <span class="token keyword">extends</span> <span class="token class-name">StreamRecord</span>
<span class="token punctuation">{</span>
    <span class="token comment">// Custom model logic goes here</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Now, whenever the blueprint is resolved, it will be an instance of the <code>TailorBlogPost</code> class.</p><h3 id="associating-tailor-to-regular-models"><a href="#associating-tailor-to-regular-models" class="header-anchor">#</a> Associating Tailor to Regular Models</h3><p>The <code>recordfinder</code> form field introduces a relation definition to a regular model, for example a model defined by a plugin. The <strong>modelClass</strong> should refer to the model class and the <strong>list</strong> property is required for singular relations, as specified by <strong>maxItems</strong>.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">products</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Products
    <span class="token key atrule">type</span><span class="token punctuation">:</span> recordfinder
    <span class="token key atrule">modelClass</span><span class="token punctuation">:</span> Acme\\Test\\Models\\Product
    <span class="token key atrule">list</span><span class="token punctuation">:</span> $/acme/test/models/product/columns.yaml
    <span class="token key atrule">maxItems</span><span class="token punctuation">:</span> <span class="token number">1</span>
</code></pre></div><p>Learn more about the <a href="./../../element/form/widget-recordfinder.html">record finder form widget here</a>.</p><h3 id="associating-regular-models-to-tailor"><a href="#associating-regular-models-to-tailor" class="header-anchor">#</a> Associating Regular Models to Tailor</h3><p>Since all tailor models share the same model class, some additional attributes are needed in your relationship definitions. The <code>Tailor\\Traits\\BlueprintRelationModel</code> implements these attributes to reference tailor models, supporting Belongs To and Belongs To Many relationships.</p><p>When the trait <code>BlueprintRelationModel</code> is implemented in your models, you can supply a <code>blueprint</code> property along with the blueprint UUID referencing the tailor blueprint. The following will establish a Belongs To relationship to the <code>Tailor\\Models\\EntryRecord</code> class called <strong>author</strong>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">Product</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">use</span> <span class="token package"><span class="token punctuation">\\</span>Tailor<span class="token punctuation">\\</span>Traits<span class="token punctuation">\\</span>BlueprintRelationModel</span><span class="token punctuation">;</span>

    <span class="token keyword">public</span> <span class="token variable">$belongsTo</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;author&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
            <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Tailor<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>EntryRecord</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;blueprint&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;6947ff28-b660-47d7-9240-24ca6d58aeae&#39;</span>
        <span class="token punctuation">]</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h3 id="building-a-custom-content-field"><a href="#building-a-custom-content-field" class="header-anchor">#</a> Building a Custom Content Field</h3><p>You may also make reference to a regular model using a implementation specific field type, for example, a customer content field may be hard coded to a <code>Customer</code> model class. This involves creating a custom tailor field that will give complete access to the model and database tables.</p><p>Inside the content field class definition, the <code>extendModelObject</code> method allows the content field to extend the record model, along with <code>extendDatabaseTable</code> to add a column to the database table.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">MyContentField</span> <span class="token keyword">extends</span> <span class="token class-name">ContentFieldBase</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">extendModelObject</span><span class="token punctuation">(</span><span class="token variable">$model</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token property">belongsTo</span><span class="token punctuation">[</span><span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">fieldName</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token class-name static-context">MyOtherModel</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>

    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">extendDatabaseTable</span><span class="token punctuation">(</span><span class="token variable">$table</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token variable">$table</span><span class="token operator">-&gt;</span><span class="token function">integer</span><span class="token punctuation">(</span><span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">fieldName</span> <span class="token operator">.</span> <span class="token string single-quoted-string">&#39;_id&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">nullable</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><p>This requires a little more effort to get things working, but the results are a simple field <strong>type</strong> definition with minimal configuration.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">myfield</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> My Field
    <span class="token key atrule">type</span><span class="token punctuation">:</span> mycontentfield
</code></pre></div><p>Learn more about building <a href="./../../extend/tailor-fields.html">custom tailor fields here</a>.</p><h4 id="see-also"><a href="#see-also" class="header-anchor">#</a> See Also</h4><div class="custom-block also"><ul><li><a href="./../../element/form/widget-recordfinder.html">RecordFinder Form Field</a></li><li><a href="./../../extend/tailor-fields.html">Building Tailor Fields</a></li></ul></div>`,79))])}const y=o(r,[["render",d]]);export{b as __pageData,y as default};
